tpRequest","typeVersion":4.2,"position":[960,0],"parameters":{"method":"POST","url":"https://studio-intelligence-production.up.railway.app/pts/class-roster","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendBody":true,"specifyBody":"json","jsonBody":"={{ {accountId:$json.accountId,studioId:$json.studioId,classId:$json.classId,...($json.documentGroupId?{roomId:$json.sourceRoomId}:{})} }}","options":{"timeout":180000}},"credentials":{"httpHeaderAuth":{"id":"li7hEi0wisqrbFlP","name":"Studio Intelligence Collector"}}},{"id":"stm-refresh-5","name":"Validate and identify source seats","type":"n8n-nodes-base.code","typeVersion":2,"position":[1200,0],"parameters":{"jsCode":"// Normalize the verified class seating table for ETL; no collection or writes.\nconst HEADERS = ['Order Id', 'Perks', 'Guest', 'Guest Email', 'Purchaser',\n  'Purchaser Email', 'Purchaser Phone', 'Checked In', 'Comments'];\nconst normalizeHeader = value => String(value).trim().replace(/\\s+/g, ' ').toLowerCase();\n\nfunction normalizeSeatingTable({ isPrivate, complete, expectedRowCount, headers, rows }) {\n  if (isPrivate !== false) throw new Error('Only classes have seating rosters');\n  if (complete !== true) throw new Error('Incomplete source seating table');\n  if (!Array.isArray(headers) || headers.length !== HEADERS.length ||\n      headers.some((value, i) => normalizeHeader(value) !== normalizeHeader(HEADERS[i]))) {\n    throw new Error('Source seating columns changed; review before importing');\n  }\n  if (!Array.isArray(rows) || !Number.isSafeInteger(expectedRowCount) ||\n      expectedRowCount < 0 || rows.length !== expectedRowCount) {\n    throw new Error('Seating row count is unverified or incomplete');\n  }\n  return rows.map((row, sourceRowIndex) => {\n    if (!Array.isArray(row) || row.length !== HEADERS.length) {\n      throw new Error('Source seating row has the wrong column count');\n    }\n    const cells = row.map((value, column) => {\n      if (value == null) return '';\n      if (typeof value === 'string') return value;\n      if (column === 0 && Number.isSafeInteger(value)) return String(value);\n      throw new Error('Expected source seating text');\n    });\n    if (!/^\\d+$/.test(cells[0])) throw new Error('Missing source order ID');\n    return {\n      // Order ID and source row index are context, not durable guest identity.\n      sourceOrderId: cells[0], sourceRowIndex,\n      perks: cells[1], guest: cells[2], guestEmail: cells[3],\n      purchaser: cells[4], purchaserEmail: cells[5], purchaserPhone: cells[6],\n      // Checked In at index 7 is intentionally excluded; Comments keeps AC.\n      comments: cells[8],\n    };\n  });\n}\n\n\n// The order grid's reservationCheckbox value is the real per-seat ID. Kendo's\n// data-uid, display order, purchaser name and order ID are not guest identities.\nfunction identifyReservations(source) {\n  const seats = normalizeSeatingTable(source);\n  if (!Array.isArray(source.reservations)) throw Error('Missing reservation identities');\n  const groups = new Map();\n  const ids = new Set();\n  // Seating's Comments can include Pinot-generated text not present in the\n  // order's Seating Requests control (observed on the real pilot). Match on\n  // order/name/email; require all imported fields identical within duplicates.\n  const signature = r => JSON.stringify([r.sourceOrderId, r.guest, r.guestEmail]);\n  for (const r of source.reservations) {\n    if (!/^\\d+$/.test(r.reservationId) || !/^\\d+$/.test(r.sourceOrderId) || ids.has(r.reservationId)) {\n      throw Error('Missing or duplicate reservation ID');\n    }\n    ids.add(r.reservationId);\n    if (!['Active', 'On Hold', 'Refunded'].includes(r.status)) throw Error('Unknown reservation status');\n    if (r.status !== 'Active') continue;\n    for (const key of ['guest', 'guestEmail', 'comments']) if (typeof r[key] !== 'string') throw Error('Incomplete reservation detail');\n    const key = signature(r);\n    if (!groups.has(key)) groups.set(key, []);\n    groups.get(key).push(r);\n  }\n  const seatGroups = new Map();\n  for (const seat of seats) {\n    const key = signature(seat);\n    if (!seatGroups.has(key)) seatGroups.set(key, []);\n    seatGroups.get(key).push(seat);\n  }\n  if (groups.size !== seatGroups.size) throw Error('Order and seating sources disagree');\n  const byIndex = new Map();\n  for (const [key, values] of seatGroups) {\n    const reservations = groups.get(key);\n    if (!reservations || reservations.length !== values.length) throw Error('Order and seating seat counts disagree');\n    // Indistinguishable guests are safe only if EVERY imported field is equal.\n    // Different perks/details on duplicate names cannot be guessed onto IDs.\n    const payload = s => JSON.stringify([s.perks, s.guest, s.guestEmail, s.purchaser, s.purchaserEmail, s.purchaserPhone, s.comments]);\n    if (new Set(values.map(payload)).size !== 1) throw Error('Ambiguous duplicate guest details');\n    reservations.sort((a, b) => a.reservationId.localeCompare(b.reservationId, 'en', { numeric: true }));\n    values.forEach((seat, i) => byIndex.set(seat.sourceRowIndex, { ...seat, reservationKey: reservations[i].reservationId }));\n  }\n  return seats.map(seat => byIndex.get(seat.sourceRowIndex));\n}\n\n\nconst payload=$input.first().json,target=$('Validate STM pilot target').first().json;\nif(payload.success!==true||payload.accountId!==target.accountId||payload.studioId!==target.studioId||payload.source?.classId!==target.classId||payload.source?.studioCode!==target.studioCode)throw Error('Wrong or incomplete source account/class');\nconst raw=payload.source;\nif(raw.details?.locationLabel!==target.sourceLocationLabel||raw.details?.roomId!==target.sourceRoomId||!target.allowedClassTypeIds?.includes(raw.details?.classTypeId))throw Error('Source room/type/location configuration mismatch');\nconst rows=identifyReservations(raw);\nreturn [{json:{classId:raw.classId,studioCode:raw.studioCode,i