ger(item.row) || item.row < 1 || item.row > rowLimit) {\n      throw new Error('Mapped row is outside the verified tab');\n    }\n    if (typeof item.reservationKey !== 'string' || !item.reservationKey.trim()) {\n      throw new Error('Missing durable reservation identity');\n    }\n    if (seenRows.has(item.row) || seenKeys.has(item.reservationKey)) {\n      throw new Error('Duplicate reservation identity or destination row');\n    }\n    seenRows.add(item.row);\n    seenKeys.add(item.reservationKey);\n    const cell = field => {\n      if (field === 'guest') return guestDisplayName(item);\n      const value = item[field];\n      if (value == null) return '';\n      if (typeof value !== 'string') throw new Error(`Expected source text for ${field}`);\n      return value;\n    };\n    data.push({ range: `${tab}!V${item.row}:AA${item.row}`, values: [IMPORT_FIELDS.map(cell)] });\n    data.push({ range: `${tab}!AC${item.row}`, values: [[cell('comments')]] });\n  }\n  return { valueInputOption: 'RAW', data };\n}\n\n\nconst FIELDS = ['perks', 'guest', 'guestEmail', 'purchaser', 'purchaserEmail', 'purchaserPhone', 'comments'];\nconst text = value => value == null ? '' : String(value);\nconst valuesOf = row => FIELDS.map(key => {\n  if (key === 'guest') return guestDisplayName(row);\n  if (row[key] != null && typeof row[key] !== 'string') throw Error('Expected literal reservation text');\n  return row[key] ?? '';\n});\n\nfunction validateTarget(target) {\n  const legacy=target?.sheetId===0&&target.sheetName==='Seating Chart Main';\n  const created=/^[a-f0-9-]{36}$/.test(target?.documentGroupId??'')&&[0,1955136908].includes(target.templateSheetId)&&target.sheetId===100000000+Number(target.classId)&&typeof target.sheetName==='string'&&target.sheetName.length<=100;\n  if (target?.studioCode !== 'STM' || target.isPrivate !== false || !(legacy||created)) {\n    throw Error('This refresh requires a registered St Matthews class tab');\n  }\n  if (!target.spreadsheetId || target.sp